#!/usr/bin/env node
// Regenerates web/data/amiibo-db.js from the pixl.js firmware's amiibo table.
//
//   node tools/build-amiibo-db.mjs path/to/db_amiibo.c
//
// Source: https://github.com/solosky/pixl.js
//         fw/application/src/amiidb/db_amiibo.c  (itself auto-generated)
//
// Vendored deliberately: the tool must not fetch anything at runtime, and this
// is the same table the device uses for its own on-screen names.

import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { join } from 'node:path';

const src = process.argv[2];
if (!src) {
  console.error('usage: node tools/build-amiibo-db.mjs <db_amiibo.c>');
  process.exit(1);
}

const text = await readFile(src, 'utf8');
// {0x01810001, 0x00440502, "[AC] 001 - Isabelle", "..."},
const re = /\{\s*0x([0-9a-fA-F]{8})\s*,\s*0x([0-9a-fA-F]{8})\s*,\s*"((?:[^"\\]|\\.)*)"\s*,\s*"((?:[^"\\]|\\.)*)"\s*\}/g;

const entries = [];
for (const m of text.matchAll(re)) {
  entries.push([`${m[1].toLowerCase()}${m[2].toLowerCase()}`, m[3].replace(/\\"/g, '"')]);
}
entries.sort((a, b) => a[0].localeCompare(b[0]));

const out = `// Generated by tools/build-amiibo-db.mjs — do not edit by hand.
//
// amiibo ID (16 hex chars, bytes 84..91 of a dump) -> English name.
// Source: solosky/pixl.js fw/application/src/amiidb/db_amiibo.c
// ${entries.length} entries.

export const AMIIBO_NAMES = Object.freeze({
${entries.map(([id, name]) => `  '${id}': ${JSON.stringify(name)},`).join('\n')}
});
`;

const dest = join(fileURLToPath(new URL('..', import.meta.url)), 'web/data/amiibo-db.js');
await writeFile(dest, out);
console.log(`wrote ${entries.length} entries to ${dest}`);
